const profileRaw = $('2. Charger Profil Candidat (Supabase)').first().json;
const profile = Array.isArray(profileRaw) && profileRaw[0] ? profileRaw[0] : { full_name: 'Jacques Alphonse Matoko' };

const jobsRaw = $('3. Récupérer Offres (Arbeit Now)').first().json;
const jobs = jobsRaw.data || [];

// Mots-clés ciblés sur le profil réel : QHSE, IA/Automatisation, Management, Lead, Tech
const keywords = ['qhse','quality','safety','hse','automat','ai','engineer','project','manager','lead','director','operations','consultant','digital','developer'];

let filtered = jobs.filter(job => {
  const text = ((job.title || '') + ' ' + (job.tags || []).join(' ') + ' ' + (job.description || '')).toLowerCase();
  return keywords.some(k => text.includes(k));
});

if (filtered.length === 0) {
  filtered = jobs;
}

const selected = filtered.slice(0, 3);

return selected.map(job => ({
  json: {
    externalId: `arbeitnow-${job.slug}`,
    title: job.title || 'Poste',
    company: job.company_name || 'Entreprise Internationale',
    location: job.location || 'Remote / International',
    source: 'ArbeitNow',
    sourceUrl: job.url || 'https://www.arbeitnow.com',
    publishedAt: job.created_at ? new Date(job.created_at * 1000).toISOString() : new Date().toISOString(),
    description: (job.description || '').replace(/<[^>]*>/g, '').slice(0, 600),
    candidateName: profile.full_name || 'Jacques Alphonse Matoko',
    candidateSkills: 'Responsable QHSE (Master QHSE, ISO 9001/14001/45001, audit, risques), Expert en Automatisation IA (N8N, Agents IA Claude/GPT-4/Groq/DeepSeek, Python, Supabase), Chef de Projet (MS Project MCA), Trilingue Français/Anglais/Russe, 10 ans expérience.'
  }
}));

