const offer = $('4. Préparer pour l\'IA').item.json;
const aiRaw = $input.item.json;

let score = 82;
let analysis = 'Profil très pertinent par rapport aux compétences requises.';

try {
  const content = aiRaw?.choices?.[0]?.message?.content || '{}';
  const match = content.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : content);
  score = Math.min(99, Math.max(65, parseInt(parsed.score) || 82));
  analysis = parsed.match_analysis || analysis;
} catch (e) {
  score = 80;
}

return {
  json: {
    external_id: offer.externalId,
    title: offer.title,
    company: offer.company,
    location: offer.location,
    source: offer.source,
    source_url: offer.sourceUrl,
    published_at: offer.publishedAt,
    score: score,
    user_id: '6222f82f-86ed-4af3-aab2-98bc754cba24',
    status: score >= 80 ? 'ready' : 'reviewing'
  }
};

